_NUM = re.compile(r"-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][+-]?[0-9]+)?")


def _number(token: str, precision: int) -> str:
    try:
        d = Decimal(token)
    except InvalidOperation:
        return token
    if d.is_zero():
        return "0"
    if precision > 0:
